def solve_a_n(N):
    if N == 1:
        return 0

    a = {1: 0}

    for n in range(2, N + 1):
        if n % 2 == 0:
            # n = 2k => k = n/2
            k = n // 2
            # a_{2k} = 2a_k + k
            a[n] = 2 * a[k] + k
        else:
            # n = 2k + 1 => k = (n-1)/2
            k = (n - 1) // 2
            # a_{2k+1} = a_k + a_{k+1} + k
            a[n] = a[k] + a[k+1] + k

    return a[N]

target_N = 2025
result = solve_a_n(target_N)
print(f"a_{target_N} = {result}")

memo = {}

def compute_a(n):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        k = n // 2
        # a_2k = 2*a_k + k
        result = 2 * compute_a(k) + k
    else:
        # a_2k+1 = a_k + a_{k+1} + k
        k = (n - 1) // 2
        result = compute_a(k) + compute_a(k + 1) + k

    memo[n] = result
    return result

# Calculate a_2025
target_n = 2025
a_2025 = compute_a(target_n)

print(f"a_{target_n} = {a_2025}")
